{
  "findings": [
    {
      "check_id": "CKV_AZURE_67",
      "title": "HTTP/2 is not enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not explicitly enable HTTP/2, so it may use the provider or platform default instead of the latest supported HTTP protocol."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "HTTPS-only access is not enforced",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not set https_only, allowing clients to attempt unencrypted HTTP connections and increasing the risk of data interception."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Function App authentication is not enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "No auth_settings block enables App Service authentication, leaving the Function App without platform-level request authentication."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n\n  site_config {\n    http2_enabled = true\n  }\n\n  auth_settings {\n    enabled = true\n  }\n}\n",
  "fix_summary": "Enforced HTTPS-only access, enabled HTTP/2, and enabled platform-level Function App authentication. Existing resource references and configuration were preserved."
}
